package com.example.markdowndesk;
import java.util.*;
public final class OutlineCheck {
    static int cases,checks,failures;static boolean controlsOnly;
    static void eq(Object expected,Object actual,String why){checks++;if(!Objects.equals(expected,actual)){failures++;System.out.println("FAIL "+why+" expected="+expected+" actual="+actual);}}
    static void run(String name,boolean control,Runnable test){if(controlsOnly&&!control)return;cases++;System.out.println("CASE "+name);test.run();}
    static MainActivity ready(int mode){MainActivity a=new MainActivity();a.mode=mode;a.renderPreview();a.deliverRender();a.acknowledge();a.settle();a.preview.scripts.clear();a.preview.appliedOffsets.clear();a.preview.appliedTokens.clear();return a;}
    static void replace(MainActivity a,int tab,String text,int mode){a.activeTab=tab;a.mode=mode;a.changed(text,true);a.renderPreview();a.deliverRender();a.acknowledge();a.main.advance(300);}
    static List<String> jumps(MainActivity a){List<String> out=new ArrayList<>();for(String s:a.preview.scripts)if(s.contains("mdScrollToSource"))out.add(s);return out;}
    public static void main(String[] args){controlsOnly=Arrays.asList(args).contains("--controls");
        run("current outline Read jump control",true,()->{MainActivity a=ready(MainActivity.MODE_PREVIEW);a.outline();var dialog=MainActivity.AlertDialog.latest;var row=dialog.row(1);int offset=MarkdownStructure.headings(a.editor.text).get(1).offset;row.click.onClick(row);eq(true,dialog.dismissed,"outline closes");eq(List.of(offset),a.preview.appliedOffsets,"real heading offset reaches current DOM");eq(MainActivity.MODE_PREVIEW,a.mode,"Read mode preserved");});
        run("current outline Write and Split source controls",true,()->{for(int mode:new int[]{MainActivity.MODE_EDIT,MainActivity.MODE_SPLIT}){MainActivity a=mode==MainActivity.MODE_EDIT?new MainActivity():ready(mode);a.mode=mode;a.outline();var row=MainActivity.AlertDialog.latest.row(1);int offset=MarkdownStructure.headings(a.editor.text).get(1).offset;row.click.onClick(row);a.editor.drain();eq(offset,a.editor.selection,"real heading selection in mode "+mode);eq(Math.max(0,offset*10-36),a.editor.y,"real deferred editor effect in mode "+mode);eq(mode,a.mode,"mode preserved");}});
        run("one pending request completes when same document becomes ready",true,()->{MainActivity a=new MainActivity();a.renderPreview();a.previewJump(13);a.deliverRender();a.acknowledge();a.viewMain.advance(180);eq(List.of(13),a.preview.appliedOffsets,"same-document readiness eventually jumps");eq(0,a.viewMain.tasks.size(),"completed retry consumed");});
        run("source link jump Read to Write control",true,()->{MainActivity a=ready(MainActivity.MODE_PREVIEW);a.handlePreviewUri(MainActivity.Uri.parse("mdsrc:12"));a.editor.drain();eq(MainActivity.MODE_EDIT,a.mode,"source jump intentionally enters Write");eq(12,a.editor.selection,"current source selection");eq(84,a.editor.y,"current source viewport");});
        run("existing guarded sync rejects replacement DOM control",true,()->{MainActivity a=ready(MainActivity.MODE_SPLIT);a.preview.holdScripts=true;a.syncFromEditor();String guarded=a.preview.queuedScripts.get(0);replace(a,1,"# B\n",MainActivity.MODE_SPLIT);a.preview.applyScript(guarded);eq(List.of(),a.preview.appliedOffsets,"model evaluates actual existing DOM identity guard");});
        run("current search keeps selected match range control",true,()->{MainActivity a=new MainActivity();a.mode=MainActivity.MODE_EDIT;SearchEngine.Options options=new SearchEngine.Options(false,false,false);int start=a.editor.text.indexOf("Target");eq(true,a.find("Target",options),"actual findNext locates match");a.editor.drain();eq(start,a.editor.selection,"find start preserved");eq(start+6,a.editor.selectionEnd,"find end preserved after select=false scroll");eq(Math.max(0,start*10-36),a.editor.y,"find viewport");a.editor.setSelection(0);a.lambda$showSearchMatches$88(SearchEngine.findAll(a.editor.text,"Target",options),null,0);a.editor.drain();eq(start,a.editor.selection,"match-list start preserved");eq(start+6,a.editor.selectionEnd,"match-list end preserved");eq(Math.max(0,start*10-36),a.editor.y,"match-list viewport");});
        run("same-source render and appearance preserve final editor intent control",true,()->{for(int mode:new int[]{MainActivity.MODE_EDIT,MainActivity.MODE_SPLIT}){MainActivity a=mode==MainActivity.MODE_EDIT?new MainActivity():ready(mode);a.mode=mode;a.sourceJump(12);a.previewFontSp+=2;a.palette=UiTheme.palette(1,true);a.renderPreview();if(mode==MainActivity.MODE_SPLIT){a.deliverRender();a.acknowledge();}a.editor.drain();eq(12,a.editor.selection,"appearance does not change selected source in mode "+mode);eq(84,a.editor.y,"same-source render does not drop explicit final effect in mode "+mode);}});
        run("old outline row rejects same-source mode ABA",false,()->{MainActivity a=ready(MainActivity.MODE_PREVIEW);String source=a.editor.text;a.outline();var row=MainActivity.AlertDialog.latest.row(1);a.changeMode(MainActivity.MODE_EDIT);a.changeMode(MainActivity.MODE_PREVIEW);a.deliverRender();a.acknowledge();a.main.advance(300);eq(source,a.editor.text,"actual mode transitions leave text unchanged");row.click.onClick(row);eq(List.of(),a.preview.appliedOffsets,"Read-Write-Read cannot revive old outline row");});
        run("deferred editor effect rejects same-source mode ABA",false,()->{MainActivity a=new MainActivity();a.mode=MainActivity.MODE_EDIT;String source=a.editor.text;a.sourceJump(12);a.changeMode(MainActivity.MODE_SPLIT);a.changeMode(MainActivity.MODE_EDIT);eq(source,a.editor.text,"actual mode transitions do not call setText");a.editor.drain();eq(0,a.editor.y,"Write-Split-Write cannot revive old editor effect");});
        run("pending outline cannot retarget another tab",false,()->{MainActivity a=new MainActivity();a.renderPreview();a.previewJump(13);replace(a,1,"# B\n\ntext\n",MainActivity.MODE_PREVIEW);a.viewMain.advance(180);eq(List.of(),a.preview.appliedOffsets,"old A jump rejected on acknowledged B");});
        run("pending outline cannot retarget edited same tab",false,()->{MainActivity a=new MainActivity();a.renderPreview();a.previewJump(13);replace(a,0,"# changed text\n",MainActivity.MODE_PREVIEW);a.viewMain.advance(180);eq(List.of(),a.preview.appliedOffsets,"old revision offset rejected");});
        run("pending outline cannot survive A to B to A",false,()->{MainActivity a=new MainActivity();a.renderPreview();a.previewJump(13);replace(a,1,"# B\n",MainActivity.MODE_PREVIEW);replace(a,0,"# restored A\n",MainActivity.MODE_PREVIEW);a.viewMain.advance(180);eq(List.of(),a.preview.appliedOffsets,"old incarnation rejected after A-B-A");});
        run("pending Read jump canceled on hidden Write mode",false,()->{MainActivity a=new MainActivity();a.renderPreview();a.previewJump(13);a.changeMode(MainActivity.MODE_EDIT);for(int i=0;i<20;i++)a.viewMain.advance(180);eq(0,a.viewMain.tasks.size(),"hidden preview does not retain retry indefinitely");eq(0,jumps(a).size(),"hidden preview untouched");});
        run("retired preview cannot keep retry chain alive",false,()->{MainActivity a=new MainActivity();a.renderPreview();a.previewJump(13);Runnable dequeued=a.viewMain.tasks.isEmpty()?null:a.viewMain.tasks.remove(0).r;a.stop();a.preview.destroyed=true;if(dequeued!=null)dequeued.run();eq(0,a.pendingIntents(),"shutdown retires pending intent");eq(0,a.viewMain.tasks.size(),"dequeued stale callback adds no retry after shutdown");});
        run("repeated outline choices retain one latest pending intent",false,()->{MainActivity a=new MainActivity();a.renderPreview();for(int i=0;i<40;i++){a.outline();var row=MainActivity.AlertDialog.latest.row(i%2);row.click.onClick(row);}eq(1,a.pendingIntents(),"one replaceable pending intent");eq(0,a.viewMain.tasks.size(),"waiting choices require no polling callbacks");a.viewMain.advance(180);eq(0,a.viewMain.tasks.size(),"no polling chains recur");a.deliverRender();a.acknowledge();a.viewMain.advance(180);eq(1,a.preview.appliedOffsets.size(),"only latest choice applied");eq(0,a.pendingIntents(),"acknowledgment consumes pending intent");eq(MarkdownStructure.headings(a.editor.text).get(1).offset,a.preview.appliedOffsets.get(0),"latest offset applied");});
        run("stale outline row rejects changed source context",false,()->{MainActivity a=ready(MainActivity.MODE_PREVIEW);a.outline();var row=MainActivity.AlertDialog.latest.row(1);replace(a,1,"# B\n",MainActivity.MODE_PREVIEW);row.click.onClick(row);eq(List.of(),a.preview.appliedOffsets,"captured A heading not applied to B");});
        run("emitted jump cannot affect replacement DOM",false,()->{MainActivity a=ready(MainActivity.MODE_PREVIEW);a.preview.holdScripts=true;a.previewJump(13);replace(a,1,"# B\n",MainActivity.MODE_PREVIEW);a.preview.drainScripts();eq(List.of(),a.preview.appliedOffsets,"DOM-side identity rejects queued A script on B");});
        run("source editor last hop rejects changed tab",false,()->{MainActivity a=ready(MainActivity.MODE_PREVIEW);a.sourceJump(12);a.activeTab=1;a.changed("# B\nbody\nmore content\n",true);a.renderPreview();a.editor.y=0;a.editor.drain();eq(0,a.editor.y,"A deferred source jump cannot scroll B editor");});
        run("source editor last hop rejects changed revision",false,()->{MainActivity a=new MainActivity();a.mode=MainActivity.MODE_EDIT;a.sourceJump(12);a.changed("# replacement\n",false);a.editor.y=0;a.editor.drain();eq(0,a.editor.y,"old source offset cannot scroll edited document");});
        run("older preview response cannot override newer Split outline choice",false,()->{MainActivity a=ready(MainActivity.MODE_SPLIT);a.preview.holdReplies=true;a.preview.sourceOffset=2;a.syncFromPreview();a.outline();var row=MainActivity.AlertDialog.latest.row(1);int offset=MarkdownStructure.headings(a.editor.text).get(1).offset;row.click.onClick(row);a.editor.drain();eq(Math.max(0,offset*10-36),a.editor.y,"new outline jump applies before held old response");a.preview.replies();a.editor.drain();eq(Math.max(0,offset*10-36),a.editor.y,"older preview synchronization cannot override newer explicit jump");});
        run("sync started after explicit request cannot override final effect",false,()->{MainActivity a=ready(MainActivity.MODE_SPLIT);a.sourceJump(12);a.preview.holdReplies=true;a.preview.sourceOffset=2;a.syncFromPreview();a.editor.drain();eq(84,a.editor.y,"explicit final effect first");a.preview.replies();a.editor.drain();eq(84,a.editor.y,"intervening old viewport result retired at final effect");});
        run("scheduled old sync retired before explicit final effect",false,()->{MainActivity a=ready(MainActivity.MODE_SPLIT);a.preview.sourceOffset=2;a.queuePreviewSync();a.sourceJump(12);a.editor.drain();a.main.advance(75);a.editor.drain();eq(84,a.editor.y,"old scheduled preview sync cannot take over");});
        run("dequeued old preview editor effect cannot override explicit jump",false,()->{MainActivity a=ready(MainActivity.MODE_SPLIT);a.preview.sourceOffset=2;a.syncFromPreview();Runnable old=a.editor.posts.remove(0);a.sourceJump(12);a.editor.drain();old.run();eq(84,a.editor.y,"already dequeued sync effect checks shared retirement");});
        run("dequeued old explicit effect cannot override newest choice",false,()->{MainActivity a=new MainActivity();a.mode=MainActivity.MODE_EDIT;a.sourceJump(12);Runnable old=a.editor.posts.remove(0);a.sourceJump(20);a.editor.drain();old.run();eq(164,a.editor.y,"explicit navigation token retires older final effect");});
        run("pending Read intent survives debounce and appearance rendering",true,()->{MainActivity a=new MainActivity();a.changed("# Changed\n\n## Target\n",false);long revision=a.sourceRevision();a.previewJump(12);eq(1,a.pendingIntents(),"one intent before debounce");a.main.advance(180);a.previewFontSp+=2;a.palette=UiTheme.palette(1,true);a.renderPreview();eq(revision,a.sourceRevision(),"render options do not change source revision");a.deliverRender();a.acknowledge();eq(List.of(12),a.preview.appliedOffsets,"latest current DOM consumes same-source intent");eq(0,a.pendingIntents(),"intent consumed once");eq(0,a.viewMain.tasks.size(),"no View polling");});
        run("suppressed identical-text load retires dequeued explicit effect",false,()->{MainActivity a=new MainActivity();a.mode=MainActivity.MODE_EDIT;a.sourceJump(12);Runnable old=a.editor.posts.remove(0);long before=a.sourceRevision();a.changed(a.editor.text,true);eq(before+1,a.sourceRevision(),"actual suppressed watcher advances source revision");old.run();eq(0,a.editor.y,"identical-text load cannot revive old effect");});
        run("same-text A to B to A rejects old pending source intent",false,()->{MainActivity a=new MainActivity();String text=a.editor.text;a.renderPreview();a.previewJump(13);replace(a,1,"# B\n",MainActivity.MODE_PREVIEW);replace(a,0,text,MainActivity.MODE_PREVIEW);eq(List.of(),a.preview.appliedOffsets,"restored exact A text cannot revive old intent");eq(0,a.pendingIntents(),"old intent retired");});
        run("lost readiness leaves one intent and zero polling",false,()->{MainActivity a=new MainActivity();a.renderPreview();a.deliverRender();a.preview.holdReplies=true;a.acknowledge();for(int i=0;i<40;i++)a.previewJump(i);eq(1,a.pendingIntents(),"latest intent retained while actual probe held");eq(1,a.preview.replies.size(),"outline adds no readiness callbacks");eq(0,a.viewMain.tasks.size(),"no poll queue while response held");a.stop();a.preview.replies();eq(0,a.pendingIntents(),"shutdown retires intent");eq(List.of(),a.preview.appliedOffsets,"late acknowledgment cannot apply jump");});
        run("dequeued explicit effect after shutdown cannot scroll",false,()->{MainActivity a=new MainActivity();a.mode=MainActivity.MODE_EDIT;a.sourceJump(12);Runnable old=a.editor.posts.remove(0);a.stop();a.preview.destroyed=true;old.run();eq(0,a.editor.y,"shutdown guard reaches final editor effect");});
        run("Split synchronization resumes from final explicit viewport",true,()->{MainActivity a=ready(MainActivity.MODE_SPLIT);a.sourceJump(12);a.editor.drain();int offset=a.viewportOffset();a.main.advance(300);eq(List.of(offset),a.preview.appliedOffsets,"new explicit viewport synchronizes to preview");eq(false,a.syncingFromEditor,"scoped suppression released");a.preview.sourceOffset=4;a.syncFromPreview();a.editor.drain();eq(4,a.editor.y,"later legitimate preview navigation still scrolls source");});
        run("missing editor layout must not scroll Split preview to zero",false,()->{MainActivity a=ready(MainActivity.MODE_SPLIT);a.sourceJump(12);a.editor.layoutAvailable=false;a.editor.drain();a.main.advance(300);eq(List.of(),a.preview.appliedOffsets,"no inferred source offset when final layout is absent");});
        run("successive ready Read jumps preserve final choice control",true,()->{MainActivity a=ready(MainActivity.MODE_PREVIEW);a.preview.holdScripts=true;a.previewJump(13);a.previewJump(22);a.preview.drainScripts();eq(22,a.preview.appliedOffsets.get(a.preview.appliedOffsets.size()-1),"ordered ready jumps finish at newest choice");});
        System.out.println((failures==0?"PASS":"RED")+" outline navigation: "+cases+" cases, "+checks+" assertions, "+failures+" failures");if(failures!=0)throw new AssertionError("Actual source outline safety failures: "+failures);
    }
}
